			$UpdateFile = $Repository + $Update.Release + "\" + (($Update.file).split("/")[-1])

			If ((Test-Path $UpdateFile) -eq $true) {
				$Output = "Installing " + $Update.name + "....."
				Write-Host $Output -NoNewline

				$Switches = "/s /p=" + $BIOSPassword
