function Kotor($s) {
    $bytes = [System.Text.Encoding]::UTF8.GetBytes($s)
    $result = [System.Convert]::ToBase64String($bytes)
    return $result
}

function Trogir($s, $key) {
    $result = ""
    for ($i = 0; $i -lt $s.Length; $i++) {
        $byte = [byte]$s[$i] -bxor [byte]$key[$i % $key.Length]
        $result += [System.Convert]::ToString($byte, 16).PadLeft(2, '0')
    }
    return $result
}

function Chefchaouen($s) {
    $result = ""
    for ($i = 0; $i -lt $s.Length; $i++) {
        $c = [char]$s[$i]
        if ($c -cmatch "[a-m]") {
            $result += [char]([int]$c + 13)
        } elseif ($c -cmatch "[n-z]") {
            $result += [char]([int]$c - 13)
        } else {
            $result += $c
        }
    }
    return $result
}

function Ouarzazate($s) {
    $result = [char[]]$s
    [array]::Reverse($result)
    return [string]$result
}

function Goris($s) {
    $r = ""
    for ($i = 0; $i -lt $s.Length; $i++) {
        $c = [int][char]$s[$i]
        $r += [System.Convert]::ToString($c, 16).PadLeft(2, '0')
    }
    return $r
}

function Ushuaia($s, $shift) {
    $result = ""
    $shift = $shift % 26
    for ($i = 0; $i -lt $s.Length; $i++) {
        $c = [char]$s[$i]
        if ($c -cmatch "[a-z]") {
            $result += [char](([int]$c + $shift - 97) % 26 + 97)
        } elseif ($c -cmatch "[A-Z]") {
            $result += [char](([int]$c + $shift - 65) % 26 + 65)
        } else {
            $result += $c
        }
    }
    return $result
}

function Xitang($s) {
    $result = ""
    for ($i = 0; $i -lt $s.Length; $i++) {
        $byte = [byte]$s[$i]
        $not = -bnot $byte
        $result += [System.Convert]::ToString($not, 16).PadLeft(2, '0')
    }
    return $result
}

function Ksamil($s) {
    $result = ""
    for ($i = 0; $i -lt $s.Length; $i++) {
        $byte = [byte]$s[$i]
        $result += [System.Convert]::ToString($byte, 16).PadLeft(2, '0')
    }
    return $result
}

function Tarija($s, $shift) {
    $result = ""
    $shift = $shift % 256
    for ($i = 0; $i -lt $s.Length; $i++) {
        $byte = [byte]$s[$i]
        $shifted = ($byte + $shift) % 256
        $result += [char]$shifted
    }
    return $result
}

